include <robotics.scad>
// Raspberry Pi Zero 2 W bare PCB. Local origin = board centre, bottom face (z=0).
L = 65; W = 30;          // official outline
t = 1.0;                 // NOT dimensioned officially (estimate)
r_corner = 3.0;          // NOT dimensioned (scaled from drawing)
hole_d = 2.75;           // NOT dimensioned (Zero-family common value, unverified)
hole_inset = 3.5;        // official
gpio_cx = 32.5; gpio_cy = 26.5;  // official (drawing coords)
pitch = 2.54; gpio_d = 1.0;      // pitch scaled from drawing; drill not dimensioned
function w(p) = [p[0] - L/2, p[1] - W/2];   // drawing -> local
$fn = 32;
difference() {
  linear_extrude(t) offset(r = r_corner) offset(delta = -r_corner) square([L, W], center = true);
  for (x = [hole_inset, L - hole_inset], y = [hole_inset, W - hole_inset])
    translate([each w([x, y]), -1]) cylinder(d = hole_d, h = t + 2);
  for (i = [0:19], j = [0:1])
    translate([each w([gpio_cx + (i - 9.5) * pitch, gpio_cy + (j - 0.5) * pitch]), -1])
      cylinder(d = gpio_d, h = t + 2, $fn = 12);
}

include <robotics.scad>
// Mini-HDMI receptacle envelope; local origin = body centre on PCB top. Opening faces -Y.
w = 10.8; d = 7.5; h = 3.3;
diff() cuboid([w, d, h], chamfer = 0.3, anchor = BOT)
  tag("remove") position(FRONT) back(1.5) cuboid([w - 1.6, 3.01, h - 1.2]);

include <robotics.scad>
// Micro-USB receptacle envelope; local origin = body centre on PCB top. Opening faces -Y.
w = 7.6; d = 5.4; h = 2.8; fl_w = 8.4; fl_d = 0.8;
difference() {
  union() {
    cuboid([w, d, h], chamfer = 0.2, anchor = BOT);
    fwd(d/2 + fl_d/2 - 0.01) cuboid([fl_w, fl_d, h + 0.2], chamfer = 0.2, anchor = BOT);
  }
  fwd(d/2 + fl_d - 1.5) up(h/2 + 0.1) cuboid([w - 1.6, 3.01, 1.6], chamfer = 0.4); // plug socket
}

